<article class="spot-card"><div class="spot-card-top"><span class="category-label">{{ \App\Support\Discovery::label($spot->category) }}</span><span>{{ $spot->area ?: 'エリア未登録' }}</span></div><div class="card-tools">@if($spot->source_checked_at)<span class="source-badge">出典あり · {{ $spot->source_checked_at->format('Y/m/d') }}</span>@endif<button type="button" class="save-place quiet-button" data-save-spot="{{ $spot->id }}" aria-pressed="false" aria-label="{{ $spot->name }}を行きたい場所に保存">♡ 行きたい</button></div><h3><a href="{{ route('spots.show',$spot) }}">{{ $spot->name }} ↗</a></h3><p>{{ \Illuminate\Support\Str::limit($spot->description ?: '施設の紹介はまだ登録されていません。',100) }}</p><div class="spot-tags">@foreach($spot->tags ?? [] as $tag)<span>#{{ \App\Support\Discovery::TAGS[$tag] ?? $tag }}</span>@endforeach</div><div class="spot-card-bottom"><span>@if($spot->reviews_count)<b class="rating">★ {{ number_format($spot->reviews_avg_rating,1) }}</b> <small>体験記 {{ $spot->reviews_count }}件</small>@else<small>体験記を募集中</small>@endif</span><label><input type="checkbox" name="ids[]" value="{{ $spot->id }}"> 比較</label></div></article>
